# =============================================================================
# LXC Sidecars Module Variables
# =============================================================================
# This module manages sidecar services for LXC containers:
#   - Backup (proxmox-backup-client with PBS)
#   - Alloy (Grafana Alloy for log/metric collection)
#   - DIUN (Docker image update notifications) - Future
# =============================================================================

# =============================================================================
# Container Information
# =============================================================================

variable "container_id" {
  description = "LXC container ID"
  type        = number
}

variable "container_ip" {
  description = "Container IP address (without CIDR)"
  type        = string
}

variable "container_name" {
  description = "Container hostname"
  type        = string
}

# =============================================================================
# Proxmox SSH Connection (for Ansible deployment)
# =============================================================================

variable "proxmox_ssh_host" {
  description = "Proxmox host SSH address"
  type        = string
}

variable "proxmox_ssh_private_key_path" {
  description = "Path to SSH private key for Proxmox host"
  type        = string
}

# =============================================================================
# Backup Configuration
# =============================================================================

variable "backup" {
  description = "Backup configuration for PBS client"
  type = object({
    enabled     = bool
    schedule    = string                    # "daily", "02:00", "Sun 03:00"
    retention   = optional(string, "7")     # Keep N backups

    # Pre-backup commands (database dumps, etc.)
    pre_backup_commands = optional(list(object({
      name    = string
      command = string
      timeout = optional(number, 300)
    })), [])

    # Paths to backup/exclude
    include_paths = optional(list(string), ["/config"])
    exclude_paths = optional(list(string), ["/var/lib/docker/overlay2"])

    # PBS server settings
    pbs_server     = optional(string, "10.100.1.102")
    pbs_datastore  = optional(string, "homelab")
    pbs_user       = optional(string, "backup@pbs")
    pbs_password_cmd = optional(string, "op read 'op://homelab/PBS - Proxmox Backup Server/password'")

    # Alert settings
    ntfy_url           = optional(string, "http://10.100.5.100:8080/backup-alerts")
    ntfy_priority      = optional(string, "default")
    ntfy_tags          = optional(string, "backup")
    ntfy_user          = optional(string, "")   # ntfy username for authentication
    ntfy_password      = optional(string, "")   # ntfy password for authentication
    notify_on_success  = optional(bool, true)   # Send notification on successful backup
    notify_on_failure  = optional(bool, true)   # Send notification on failed backup (recommended: always true)
  })
  default = null

  validation {
    condition = var.backup == null || (
      var.backup.schedule == "daily" ||
      can(regex("^[0-9]{2}:[0-9]{2}$", var.backup.schedule)) ||
      can(regex("^(mon|tue|wed|thu|fri|sat|sun) [0-9]{2}:[0-9]{2}$", lower(var.backup.schedule)))
    )
    error_message = "Schedule must be 'daily', 'HH:MM', or 'day HH:MM' (e.g., 'Sun 03:00')."
  }
}

# =============================================================================
# Container Management Agents
# =============================================================================

variable "pulse_agent" {
  description = "Pulse Docker agent configuration for container monitoring"
  type = object({
    enabled     = optional(bool, false)
    pulse_url   = optional(string, "http://10.100.1.104:7655")
    pulse_token = optional(string, "")
  })
  default = {}

  validation {
    condition = try(var.pulse_agent.enabled, false) == false || try(var.pulse_agent.pulse_token, "") != ""
    error_message = "If pulse_agent is enabled, pulse_token must be provided."
  }
}

variable "arcane_agent" {
  description = "Arcane remote agent configuration for container management"
  type = object({
    enabled         = optional(bool, false)
    manager_url     = optional(string, "http://10.100.1.104:3552")
    bootstrap_token = optional(string, "")
  })
  default = {}

  validation {
    condition = try(var.arcane_agent.enabled, false) == false || try(var.arcane_agent.bootstrap_token, "") != ""
    error_message = "If arcane_agent is enabled, bootstrap_token must be provided."
  }
}

# =============================================================================
# Grafana Alloy Agent
# =============================================================================

variable "alloy_agent" {
  description = "Grafana Alloy agent for log/metric collection to Loki/Prometheus"
  type = object({
    enabled        = optional(bool, false)
    loki_url       = optional(string, "https://loki-push.homelab.rambtech.dev")
    prometheus_url = optional(string, "https://prometheus-push.homelab.rambtech.dev")
    username       = optional(string, "")
    password       = optional(string, "")
  })
  default = {}

  validation {
    condition = try(var.alloy_agent.enabled, false) == false || (
      try(var.alloy_agent.username, "") != "" && try(var.alloy_agent.password, "") != ""
    )
    error_message = "If alloy_agent is enabled, username and password must be provided for authentication."
  }
}

# =============================================================================
# Future Sidecars (Placeholder)
# =============================================================================

variable "diun_enabled" {
  description = "Enable DIUN for Docker image update notifications"
  type        = bool
  default     = false
}

{
  "name": "Discord AI Assistant",
  "nodes": [
    {
      "parameters": {
        "httpMethod": "POST",
        "path": "discord-updates",
        "responseMode": "responseNode",
        "options": {
          "responseData": "allEntries"
        }
      },
      "id": "webhook-trigger",
      "name": "Discord Webhook",
      "type": "n8n-nodes-base.webhook",
      "position": [
        180,
        300
      ],
      "typeVersion": 2.1,
      "webhookId": "discord-updates",
      "onError": "continueRegularOutput"
    },
    {
      "parameters": {
        "assignments": {
          "assignments": [
            {
              "id": "user_message",
              "name": "user_message",
              "type": "string",
              "value": "={{ $json.body.message }}"
            },
            {
              "id": "user_id",
              "name": "user_id",
              "type": "string",
              "value": "={{ $json.body.userId }}"
            },
            {
              "id": "user_name",
              "name": "user_name",
              "type": "string",
              "value": "={{ $json.body.userName }}"
            },
            {
              "id": "channel_id",
              "name": "channel_id",
              "type": "string",
              "value": "={{ $json.body.channelId }}"
            },
            {
              "id": "is_dm",
              "name": "is_dm",
              "type": "boolean",
              "value": "={{ $json.body.isDM }}"
            }
          ]
        },
        "options": {}
      },
      "id": "extract-message",
      "name": "Extract Message",
      "type": "n8n-nodes-base.set",
      "position": [
        380,
        300
      ],
      "typeVersion": 3.4
    },
    {
      "parameters": {
        "promptType": "define",
        "text": "={{ $json.user_message }}",
        "hasOutputParser": false,
        "options": {
          "systemMessage": "You are a Docker Update Assistant for a homelab. You MUST use tools to get real data - NEVER make up or guess version numbers.\n\nCRITICAL RULES:\n1. When asked about updates, you MUST call the check_updates tool first. Do NOT fabricate update information.\n2. When asked about changelogs, you MUST call the fetch_changelog tool. Do NOT make up release notes.\n3. If a tool fails, say so honestly. Never invent data.\n4. Do NOT @mention users or roles.\n\nTools available:\n- check_updates: Gets real update data from DIUN (Docker Image Update Notifier)\n- fetch_changelog: Gets real release notes from GitHub\n\nGitHub repos for changelogs:\n- immich-app/immich, grafana/grafana, n8nio/n8n, jellyfin/jellyfin, goauthentik/authentik, traefik/traefik\n\nKeep responses concise (<1800 chars) and use minimal markdown."
        }
      },
      "id": "ai-agent",
      "name": "AI Agent",
      "type": "@n8n/n8n-nodes-langchain.agent",
      "position": [
        600,
        300
      ],
      "typeVersion": 3.1,
      "onError": "continueErrorOutput"
    },
    {
      "parameters": {
        "model": {
          "__rl": true,
          "mode": "id",
          "value": "qwen2.5-1.5b-instruct-q4_k_m"
        },
        "options": {
          "baseURL": "http://10.100.5.101:8080/v1",
          "temperature": 0.3,
          "maxTokens": 2048
        }
      },
      "id": "openai-model",
      "name": "OpenAI Chat Model",
      "type": "@n8n/n8n-nodes-langchain.lmChatOpenAi",
      "position": [
        480,
        520
      ],
      "typeVersion": 1.3
    },
    {
      "parameters": {
        "sessionIdType": "customKey",
        "sessionKey": "={{ $('Extract Message').item.json.user_id }}"
      },
      "id": "memory",
      "name": "Window Buffer Memory",
      "type": "@n8n/n8n-nodes-langchain.memoryBufferWindow",
      "position": [
        620,
        520
      ],
      "typeVersion": 1.3
    },
    {
      "parameters": {
        "toolDescription": "Check for available Docker container updates across all LXC containers in the homelab. Returns a summary of containers that have updates available. No parameters needed.",
        "method": "GET",
        "url": "http://localhost:5678/webhook/docker-update-checker",
        "authentication": "none",
        "optimizeResponse": true
      },
      "id": "tool-check-updates",
      "name": "Check Updates",
      "type": "@n8n/n8n-nodes-langchain.toolHttpRequest",
      "position": [
        760,
        520
      ],
      "typeVersion": 1.1
    },
    {
      "parameters": {
        "toolDescription": "Fetch changelog/release notes for a Docker image from GitHub. Use this when users want to know what changed in a specific container update. Provide the GitHub repository in owner/repo format (e.g., 'immich-app/immich', 'grafana/grafana', 'n8nio/n8n'). Returns the latest release notes.",
        "method": "GET",
        "url": "https://api.github.com/repos/{repository}/releases/latest",
        "authentication": "none",
        "sendHeaders": true,
        "headerParameters": {
          "parameters": [
            {
              "name": "Accept",
              "value": "application/vnd.github.v3+json"
            },
            {
              "name": "User-Agent",
              "value": "n8n-discord-bot"
            }
          ]
        },
        "placeholderDefinitions": {
          "values": [
            {
              "name": "repository",
              "description": "The GitHub repository in owner/repo format (e.g., 'immich-app/immich', 'grafana/grafana')"
            }
          ]
        },
        "optimizeResponse": true
      },
      "id": "tool-fetch-changelog",
      "name": "Fetch Changelog",
      "type": "@n8n/n8n-nodes-langchain.toolHttpRequest",
      "position": [
        900,
        520
