    {
      "parameters": {
        "jsCode": "const allContainers = [];\nconst seenImages = new Set();\nconst lxcItems = $('Split LXCs').all();\nconst sshItems = $input.all();\n\nfunction parseImage(image) {\n  let registry = 'docker.io', repository = image, tag = 'latest';\n  const tagMatch = repository.match(/^(.+):([^:]+)$/);\n  if (tagMatch) { repository = tagMatch[1]; tag = tagMatch[2]; }\n  if (repository.includes('/')) {\n    const firstPart = repository.split('/')[0];\n    if (firstPart.includes('.') || firstPart.includes(':')) {\n      registry = firstPart;\n      repository = repository.substring(firstPart.length + 1);\n    }\n  }\n  if (!repository.includes('/') && registry === 'docker.io') repository = 'library/' + repository;\n  return { registry, repository, current_tag: tag };\n}\n\nfor (let i = 0; i < sshItems.length; i++) {\n  const stdout = sshItems[i].json.stdout || '';\n  const lxcId = lxcItems[i]?.json?.id || 'unknown';\n  const lxcName = lxcItems[i]?.json?.name || 'unknown';\n  \n  for (const line of stdout.split('\\n')) {\n    if (!line.trim() || line === '{}') continue;\n    try {\n      const container = JSON.parse(line);\n      const name = container.Names || '', image = container.Image || '';\n      if (name && image && !seenImages.has(image)) {\n        seenImages.add(image);\n        allContainers.push({ json: { lxcId, lxcName, containerName: name, image, skip: false, ...parseImage(image) } });\n      }\n    } catch (e) {}\n  }\n}\n\nreturn allContainers.length ? allContainers : [{ json: { skip: true, skip_reason: 'No containers found' } }];"
      },
      "id": "parse-containers",
      "name": "Parse Container Info",
      "type": "n8n-nodes-base.code",
