      "parameters": {
        "jsCode": "const updates = $input.item.json.data || [];\nconst ntfyUrl = $('Configuration').first().json.ntfy_url;\n\nif (!updates.length) return [{ json: { skip: true } }];\n\n// Group by LXC for template\nconst byLxc = {};\nfor (const u of updates) {\n  if (!byLxc[u.lxcName]) byLxc[u.lxcName] = [];\n  byLxc[u.lxcName].push({ name: u.containerName, current: u.current_tag, latest: u.latest_tag });\n}\n\n// Build structured data for ntfy template\nconst templateData = {\n  title: `${updates.length} Docker Updates`,\n  updates: Object.entries(byLxc).map(([lxcName, containers]) => ({ lxcName, containers }))\n};\n\nconst actions = updates.slice(0, 3).map(u => ({ action: 'view', label: u.containerName.slice(0, 12), url: u.releaseUrl }));\n\nreturn [{ json: { ntfy_url: ntfyUrl, ...templateData, priority: 3, tags: ['whale', 'arrow_up'], actions } }];"
