        "parameters": {
          "jsCode": "const results = [];\nfor (const item of $input.all()) {\n  const c = item.json;\n  if (c.skip) { results.push({ json: c }); continue; }\n  \n  const { registry, repository: repo, current_tag: tag } = c;\n  if (!tag || tag.startsWith('sha256:')) { results.push({ json: { ...c, skip: true } }); continue; }\n  \n  let apiUrl = '', releaseUrl = '', registryType = '';\n  if (registry === 'docker.io' || registry === 'docker.n8n.io') {\n    registryType = 'dockerhub';\n    apiUrl = `https://hub.docker.com/v2/repositories/${repo}/tags?page_size=100`;\n    releaseUrl = `https://hub.docker.com/r/${repo.replace('library/', '')}/tags`;\n  } else if (registry === 'ghcr.io') {\n    registryType = 'ghcr';\n    const [owner, ...parts] = repo.split('/');\n    apiUrl = `https://api.github.com/users/${owner}/packages/container/${parts.join('/')}/versions?per_page=50`;\n    releaseUrl = `https://github.com/${repo}/pkgs/container/${parts.join('/')}`;\n  } else if (registry === 'lscr.io') {\n    registryType = 'lscr';\n    const repoName = repo.replace('linuxserver/', '');\n    apiUrl = `https://api.github.com/repos/linuxserver/docker-${repoName}/releases?per_page=20`;\n    releaseUrl = `https://github.com/linuxserver/docker-${repoName}/releases`;\n  } else { results.push({ json: { ...c, skip: true } }); continue; }\n  \n  results.push({ json: { ...c, apiUrl, releaseUrl, registryType } });\n}\nreturn results;"
